/// <summary>
/// Reversé depuis lapis::CNC_CZ_ClientChangeClassShortcut (ZoneServer).
/// Wire natif (désasm Serialize @0x82023a0) :
///   [u8 barCount] puis par barre : [u16 mask — bit(i) = slot i rempli,
///   PAS de sentinelle (contrairement au 351/352)] [i32 par bit levé]
///   puis en fin : [u16 extrasCount][i32 par extra].
/// Emis au changement de classe avec les PAGES de la NOUVELLE classe
/// (relais de CNE_DBA_ClientShortcut — char+0x684 natif, une entrée
/// par page, pas par classe).
/// </summary>
public sealed class CNC_CZ_ClientChangeClassShortcut : NetCommand
{
    public override int Opcode => 510;
    public override string Name => "CNC_CZ_ClientChangeClassShortcut";

    /// <summary>Barres (pages) de la classe active — 10 slots chacune,
    /// -1 = vide.</summary>
    public System.Collections.Generic.List<
        CNC_CZ_ClientEnterNodeShortcut.ShortcutBar> Bars { get; }
        = new();

    /// <summary>Vecteur int global (char+0x678 natif).</summary>
    public System.Collections.Generic.List<int> Extras { get; }
        = new();

    public override void Serialize(OutBinStream stream)
    {
        stream.WriteByte((byte)Bars.Count);
        foreach (var bar in Bars)
        {
            // Natif @0x82023a0 : mask bit(i) = slot i rempli (local_24
            // shifté par index, aucune sentinelle — ≠ 351/352).
            var mask = 0;
            var slotCount = Math.Min(bar.Slots.Count, 10);
            // "Rempli" = != -1 ET != 0 — un 0 persisté est un slot
            // fantôme (bug live : bit levé + i32 écrit → désalignement).
            for (var i = 0; i < slotCount; i++)
                if (bar.Slots[i] != -1 && bar.Slots[i] != 0)
                    mask |= 1 << i;
            stream.WriteShort((short)mask);
            for (var i = 0; i < slotCount; i++)
                if (bar.Slots[i] != -1 && bar.Slots[i] != 0)
                    stream.WriteInt(bar.Slots[i]);
        }
        stream.WriteShort((short)Extras.Count);
        foreach (var v in Extras)
            stream.WriteInt(v);
    }

    public override void Deserialize(InBinStream input)
    {
        var barCount = input.ReadByte();
        Bars.Clear();
        for (var b = 0; b < barCount; b++)
        {
            var bar = new CNC_CZ_ClientEnterNodeShortcut.ShortcutBar();
            var mask = (ushort)input.ReadShort();
            for (var i = 0; i < 10; i++)
                bar.Slots.Add(((mask >> i) & 1) != 0
                    ? input.ReadInt() : -1);
            Bars.Add(bar);
        }
        Extras.Clear();
        var extraCount = (ushort)input.ReadShort();
        for (var i = 0; i < extraCount; i++)
            Extras.Add(input.ReadInt());
    }
}

