/// <summary>
/// Reversé depuis lapis::CNC_CZ_ClientEnterNodeShortcut (ZoneServer).
/// Champs C++ originaux : ushort, ushort, ushort, int, int
/// </summary>
public sealed class CNC_CZ_ClientEnterNodeShortcut : NetCommand
{
    public override int Opcode => 351;
    public override string Name => "CNC_CZ_ClientEnterNodeShortcut";

    /// <summary>
    /// Barres de raccourcis — layout natif vérifié (0x8202200) :
    /// ushort barCount, puis par barre :
    ///   ushort bitmask — bit0=1 sentinelle "barre vide", sinon le slot i
    ///   occupe le bit (i+1) et bit0 est effacé (natif :
    ///   `mask=(mask|(1&lt;&lt;(i+1)))&amp;~1`, mask=1 si aucun slot),
    ///   int par slot marqué,
    ///   ushort extraCount + int par extra.
    /// </summary>
    public System.Collections.Generic.List<ShortcutBar> Bars { get; }
        = new();

    public sealed class ShortcutBar
    {
        /// <summary>Valeurs des slots (-1 = vide), max 10.</summary>
        public System.Collections.Generic.List<int> Slots { get; }
            = new();
        /// <summary>Vecteur int additionnel sérialisé après les slots.</summary>
        public System.Collections.Generic.List<int> Extras { get; }
            = new();
    }

    public override void Serialize(OutBinStream output)
    {
        output.WriteShort((short)Bars.Count);
        foreach (var bar in Bars)
        {
            // Natif @0x8202200 : bit0=1 = sentinelle vide ; slot i →
            // bit (i+1) et bit0 effacé dès qu'un slot est occupé.
            var mask = 1;
            var slotCount = Math.Min(bar.Slots.Count, 10);
            for (var i = 0; i < slotCount; i++)
                if (bar.Slots[i] != -1)
                    mask = (mask | (1 << (i + 1))) & ~1;
            output.WriteShort((short)mask);
            for (var i = 0; i < slotCount; i++)
                if (bar.Slots[i] != -1)
                    output.WriteInt(bar.Slots[i]);
            output.WriteShort((short)bar.Extras.Count);
            foreach (var v in bar.Extras)
                output.WriteInt(v);
        }
    }

    public override void Deserialize(InBinStream input)
    {
        var barCount = (ushort)input.ReadShort();
        Bars.Clear();
        for (var b = 0; b < barCount; b++)
        {
            var bar = new ShortcutBar();
            var mask = (ushort)input.ReadShort();
            for (var i = 0; i < 10; i++)
                // Natif : slot i ↔ bit (i+1) — bit0 est la sentinelle.
                bar.Slots.Add(((mask >> (i + 1)) & 1) != 0
                    ? input.ReadInt() : -1);
            var extraCount = (ushort)input.ReadShort();
            for (var i = 0; i < extraCount; i++)
                bar.Extras.Add(input.ReadInt());
            Bars.Add(bar);
        }
    }
}

