public sealed class CNC_CZ_ClientReceiveShortcutOfPage : NetCommand
{
    public override int Opcode => 352;
    public override string Name => "CNC_CZ_ClientReceiveShortcutOfPage";

    /// <summary>Page de raccourcis demandée (s16).</summary>
    public short Page { get; set; }
    /// <summary>Bit0 = sentinelle page vide, bit(i+1) = slot i rempli.</summary>
    public ushort Mask { get; set; }
    /// <summary>Valeurs i32 des slots marqués, écrites dans l'ordre.</summary>
    public int[] Values { get; set; } = System.Array.Empty<int>();
    /// <summary>Extras i32 traînant (u16 count + valeurs).</summary>
    public int[] Extras { get; set; } = System.Array.Empty<int>();

    // Serialize natif @0x08202540 : s16 page, u16 mask, i32 conditionnels
    // par flag byte, puis vecteur i32 final.
    public override void Serialize(OutBinStream stream)
    {
        stream.WriteShort(Page);
        stream.WriteShort((short)Mask);
        foreach (var v in Values) stream.WriteInt(v);
        stream.WriteShort((short)Extras.Length);
        foreach (var v in Extras) stream.WriteInt(v);
