        Mask = (ushort)stream.ReadShort();
        var bits = new System.Collections.Generic.List<int>();
        for (var i = 1; i < 16; i++)
            if ((Mask & (1 << i)) != 0) bits.Add(i);
        Values = new int[bits.Count];
        for (var i = 0; i < bits.Count; i++) Values[i] = stream.ReadInt();
        var n = (ushort)stream.ReadShort();
        Extras = new int[n];
        for (var i = 0; i < n; i++) Extras[i] = stream.ReadInt();
    }
}

/// <summary>
/// Reversé depuis lapis::CNC_CZ_ClientRecommendActivities (ZoneServer).
/// Champs C++ originaux : short, int, ushort, ushort, uint, byte, ushort, ushort
/// </summary>
public sealed class CNC_CZ_ClientRecommendActivities : NetCommand
{
    public override int Opcode => 559;
    public override string Name => "CNC_CZ_ClientRecommendActivities";

    // Wire natif (Serialize @zone) :
    // [s16][i32 ts][u16 n][n×{u16 id,u32 count,u8 flag}][u16 m][m×u16]
    // — le générateur avait aplati les deux collections.

    /// <summary>s16 d'en-tête (0 dans le natif — champ this+4).</summary>
    public short Field1 { get; set; }
    /// <summary>i32 : recommend_activities_time (cache char+0xc88).</summary>
    public int Field2 { get; set; }
    /// <summary>Activités : id, progression, flag "finished".</summary>
    public List<(ushort Id, uint Count, byte Flag)> Entries { get; } = new();
    /// <summary>Vecteur u16 final : ids tracés (ed+0x7c4 natif).</summary>
    public List<ushort> Tracing { get; } = new();

    public override void Serialize(OutBinStream stream)
    {
        stream.WriteShort(Field1);                    // s16 en-tête (0)
        stream.WriteInt(Field2);                      // i32 timestamp
        stream.WriteShort((short)Entries.Count);      // u16 n
        foreach (var (id, count, flag) in Entries)
        {
            stream.WriteShort((short)id);             // u16 recommend_id
            stream.WriteInt((int)count);              // u32 progression
            stream.WriteByte(flag);                   // u8 finished/tracé
        }
        stream.WriteShort((short)Tracing.Count);      // u16 m
        foreach (var t in Tracing)
            stream.WriteShort((short)t);              // u16 id tracé
    }

    public override void Deserialize(InBinStream stream)
    {
        Field1 = stream.ReadShort();
        Field2 = stream.ReadInt();
        Entries.Clear();
        var n = (ushort)stream.ReadShort();
        for (var i = 0; i < n; i++)
        {
            var id = (ushort)stream.ReadShort();
            var count = (uint)stream.ReadInt();
            var flag = stream.ReadByte();
            Entries.Add((id, count, flag));
        }
        Tracing.Clear();
        var m = (ushort)stream.ReadShort();
        for (var i = 0; i < m; i++)
            Tracing.Add((ushort)stream.ReadShort());
    }
}

