/// <summary>
/// Reversé depuis lapis::CNE_CZ_ZoneServerPlayerLicense (ZoneServer).
/// Wire natif (`Deserialize` @0x8272a20) : `[u16 count]` puis
/// `count × {[s16 licenseId][u8 slot]}` (map licence→slot,
/// slot 1..7, 0 = déséquiper) puis `[s16 classId]` en +0x2c —
/// classe ciblée (courante → SetCurrentClassLicense @0x82714f0,
/// autre → SetOtherClassLicense @0x82717f0). L'ancien format fixe
/// `[u16][s16][u8][s16]` était faux.
/// </summary>
public sealed class CNE_CZ_ZoneServerPlayerLicense : NetCommand
{
    public override int Opcode => 182;
    public override string Name => "CNE_CZ_ZoneServerPlayerLicense";

    /// <summary>Paires (licenseId s16, slot u8) demandées — le
    /// natif stocke dans un rb_tree trié par id.</summary>
    public List<(short LicenseId, byte Slot)> Selections { get; }
        = new();
    /// <summary>classId cible (s16) — champ +0x2c natif.</summary>
    public short ClassId { get; set; }

    public override void Serialize(OutBinStream stream)
    {
        stream.WriteShort((short)Selections.Count); // u16 count
        foreach (var (lic, slot) in Selections)
        {
            stream.WriteShort(lic);   // s16 id licence
            stream.WriteByte(slot);   // u8 slot
        }
        stream.WriteShort(ClassId);   // s16 classId (+0x2c)
    }

    public override void Deserialize(InBinStream stream)
    {
        var count = (ushort)stream.ReadShort();  // u16 count
        for (var i = 0; i < count; i++)
        {
            var lic = stream.ReadShort();        // s16 licenseId
            var slot = stream.ReadByte();        // u8 slot
            Selections.Add((lic, slot));
        }
        ClassId = stream.ReadShort();            // s16 classId
    }
}

