/// Reversé depuis lapis::CNE_CZ_ZoneServerQueryLicenseSet (ZoneServer).
/// Wire natif (`Deserialize` @0x8277a20) : `[u16 count]` puis
/// `count × u16 licenseId` — le **dernier** u16 est le flag de
/// moitié (`InvokeSpellStonesSet` @0x8418aa0 : le client envoie
/// les ids des certs du combo + flag 0 = slots 1-4, 1 = slots 4-7).
/// </summary>
public sealed class CNE_CZ_ZoneServerQueryLicenseSet : NetCommand
{
    public override int Opcode => 183;
    public override string Name => "CNE_CZ_ZoneServerQueryLicenseSet";

    /// <summary>Ids demandés — les `Count-1` premiers sont les ids
    /// de certificats, le dernier est le flag de moitié (0/1).</summary>
    public List<ushort> LicenseIds { get; } = new();

    public override void Serialize(OutBinStream stream)
    {
        stream.WriteShort((short)LicenseIds.Count); // u16 count
        foreach (var id in LicenseIds)
            stream.WriteShort((short)id);           // u16 id
    }

    public override void Deserialize(InBinStream stream)
    {
        var count = (ushort)stream.ReadShort();     // u16 count
        for (var i = 0; i < count; i++)
            LicenseIds.Add((ushort)stream.ReadShort()); // u16 id
    }
}

